#!/bin/bash
# ============================================================
# FIX: Roles con group_access "all" ahora ven todos los dispositivos
# ============================================================
set -e

CONTEO_DIR="/opt/siempria-monitor"
BACKUP_DIR="$CONTEO_DIR/backups/$(date +%Y%m%d_%H%M%S)"
SERVICE_NAME="siempria-monitor"
TMPDIR="$(mktemp -d)"

echo "============================================"
echo "  FIX: Permisos de Roles (Tecnico, etc.)"
echo "============================================"
echo ""

echo "[1/4] Extrayendo archivos..."
PAYLOAD=""
echo "$PAYLOAD" | base64 -d | tar xzf - -C "$TMPDIR"
echo "   OK"

echo "[2/4] Backup..."
mkdir -p "$BACKUP_DIR"
cp "$CONTEO_DIR/backend/services/multitenancy_service.py" "$BACKUP_DIR/" 2>/dev/null || true
cp "$CONTEO_DIR/backend/routes/devices.py" "$BACKUP_DIR/" 2>/dev/null || true
cp "$CONTEO_DIR/backend/routes/dahua.py" "$BACKUP_DIR/" 2>/dev/null || true
cp "$CONTEO_DIR/backend/routes/organizations.py" "$BACKUP_DIR/" 2>/dev/null || true
echo "   Backup en: $BACKUP_DIR"

echo "[3/4] Aplicando fix..."
cp "$TMPDIR/multitenancy_service.py" "$CONTEO_DIR/backend/services/multitenancy_service.py"
cp "$TMPDIR/devices.py" "$CONTEO_DIR/backend/routes/devices.py"
cp "$TMPDIR/dahua.py" "$CONTEO_DIR/backend/routes/dahua.py"
cp "$TMPDIR/organizations.py" "$CONTEO_DIR/backend/routes/organizations.py"
echo "   4 archivos actualizados"

rm -rf "$TMPDIR"

echo "[4/4] Reiniciando servicio..."
sudo systemctl restart "$SERVICE_NAME" 2>/dev/null || true
sleep 3

if sudo systemctl is-active --quiet "$SERVICE_NAME" 2>/dev/null; then
    echo ""
    echo "============================================"
    echo "  FIX APLICADO CORRECTAMENTE"
    echo "============================================"
    echo "  Ahora los roles con group_access='all'"
    echo "  (como Tecnico) veran TODOS los dispositivos"
    echo "  Backup en: $BACKUP_DIR"
    echo "============================================"
else
    echo "[!] Servicio no activo. Revisa:"
    echo "    sudo systemctl status $SERVICE_NAME"
    echo "    sudo journalctl -u $SERVICE_NAME -n 50"
fi
